# ---------------------------------------------------------------- 2-сабақ
LAMPORT = ("# Әр процестің оқиғалары: ('local',) | ('send', кімге, хабар_id) | ('recv', хабар_id)\n"
           "procs = {\n"
           "    'A': [('local',), ('send', 'B', 'm1'), ('local',), ('recv', 'm3')],\n"
           "    'B': [('recv', 'm1'), ('send', 'C', 'm2'), ('local',)],\n"
           "    'C': [('local',), ('local',), ('recv', 'm2'), ('send', 'A', 'm3')],\n"
           "}\n\n"
           "def lamport(procs):\n"
           "    clock = {p: 0 for p in procs}\n"
           "    pos = {p: 0 for p in procs}\n"
           "    stamp_of_msg, out = {}, {p: [] for p in procs}\n"
           "    progress = True\n"
           "    while progress:\n"
           "        progress = False\n"
           "        for p, evs in procs.items():\n"
           "            while pos[p] < len(evs):\n"
           "                e = evs[pos[p]]\n"
           "                if e[0] == 'recv':\n"
           "                    if e[1] not in stamp_of_msg:\n"
           "                        break          # хабар әлі жіберілмеген - күтеміз\n"
           "                    clock[p] = max(clock[p], stamp_of_msg[e[1]]) + 1\n"
           "                else:\n"
           "                    clock[p] += 1\n"
           "                    if e[0] == 'send':\n"
           "                        stamp_of_msg[e[2]] = clock[p]\n"
           "                out[p].append(clock[p])\n"
           "                pos[p] += 1\n"
           "                progress = True\n"
           "    return out\n\n"
           "for p, ts in lamport(procs).items():\n"
           "    print(p, ts)")

