VEC = ("PROCS = ['A', 'B', 'C']\n\n"
       "def tick(v, p):\n"
       "    v = dict(v); v[p] += 1; return v\n\n"
       "def merge(v, w, p):\n"
       "    m = {q: max(v[q], w[q]) for q in PROCS}\n"
       "    m[p] += 1\n"
       "    return m\n\n"
       "def compare(v, w):\n"
       "    le = all(v[q] <= w[q] for q in PROCS)\n"
       "    ge = all(v[q] >= w[q] for q in PROCS)\n"
       "    if le and ge: return 'тең'\n"
       "    if le: return 'бұрын (→)'\n"
       "    if ge: return 'кейін (←)'\n"
       "    return 'параллель (∥)'\n\n"
       "zero = {q: 0 for q in PROCS}\n"
       "a1 = tick(zero, 'A')                 # A: жергілікті\n"
       "a2 = tick(a1, 'A')                   # A: B-ге жібереді\n"
       "c1 = tick(zero, 'C')                 # C: жергілікті\n"
       "b1 = merge(zero, a2, 'B')            # B: A-дан алады\n"
       "b2 = tick(b1, 'B')                   # B: C-ға жібереді\n"
       "c2 = merge(c1, b2, 'C')              # C: B-дан алады\n"
       "for name, v in [('a1', a1), ('a2', a2), ('c1', c1), ('b1', b1), ('b2', b2), ('c2', c2)]:\n"
       "    print(name, [v[q] for q in PROCS])\n"
       "print('a1 vs c2:', compare(a1, c2))\n"
       "print('a2 vs c1:', compare(a2, c1))\n"
       "print('c2 vs b1:', compare(c2, b1))")

