QUORUM = ("import itertools\n\n"
          "N = 5\n"
          "replicas = list(range(N))\n\n"
          "def always_overlap(R, W):\n"
          "    \"\"\"кез келген W-жиын мен R-жиын қиылыса ма (толық іріктеу)\"\"\"\n"
          "    for w in itertools.combinations(replicas, W):\n"
          "        for r in itertools.combinations(replicas, R):\n"
          "            if not set(w) & set(r):\n"
          "                return False, (w, r)\n"
          "    return True, None\n\n"
          "for R, W in [(1, 5), (2, 4), (3, 3), (2, 3), (1, 1)]:\n"
          "    ok, bad = always_overlap(R, W)\n"
          "    print(f'R={R} W={W} R+W={R + W}:', 'әрқашан қиылысады' if ok else f'қиылыспауы мүмкін: жазу {bad[0]}, оқу {bad[1]}')")

