LIN = ("import itertools\n\n"
       "# Тарих: (клиент, амал, мән, басталу, аяқталу). Бір регистр, бастапқы мәні 0.\n"
       "history = [\n"
       "    ('A', 'write', 1, 0, 3),\n"
       "    ('B', 'read',  1, 1, 2),     # A-ның жазуы аяқталмай тұрып 1-ді көрді\n"
       "    ('C', 'read',  0, 4, 5),     # A-ның жазуы аяқталғаннан кейін 0 - мүмкін бе?\n"
       "]\n\n"
       "def legal(order):\n"
       "    value = 0\n"
       "    for _, op, v, _, _ in order:\n"
       "        if op == 'write':\n"
       "            value = v\n"
       "        elif v != value:\n"
       "            return False\n"
       "    return True\n\n"
       "def respects_real_time(order):\n"
       "    pos = {id(x): i for i, x in enumerate(order)}\n"
       "    return all(pos[id(a)] < pos[id(b)] for a in order for b in order if a[4] < b[3])\n\n"
       "def linearizable(h):\n"
       "    return any(legal(o) and respects_real_time(o) for o in itertools.permutations(h))\n\n"
       "print('сызықтық:', linearizable(history))\n"
       "fixed = history[:2] + [('C', 'read', 1, 4, 5)]\n"
       "print('C 1 оқыса:', linearizable(fixed))")

